use crate::aap::caps::{http_client, state_read};

struct Node;

fn url_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (approved grant). RunInfo has no text field, so the
        // run date serves as the query. The result is ignored so the output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            url_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = match state_read::get("subscriptions") {
            Some(text) => text
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

Two assumptions to check:
- **State key:** `RunInfo` has no text field, so the enrichment query uses `info.date`. The state key `"subscriptions"` is a guess, with the value read as newline-separated URLs.
- **Fetch result:** the `http-client` `fetch` result is discarded, so a failed or refused fetch does not change the node's output.

